"""
Management command: populate_warmachine_products

Creates the Warmachine product line as a new top-level Category (no Faction
subdivision -- standalone game system, same pattern as Star Wars: Legion /
Halo: Flashpoint).

MSRP/images/URLs come from Steamforged Games' own store (warmachine.gg), not
Games Workshop. This category has no GW retailer row at all -- product.msrp
still drives the site's MSRP/discount reference via the existing fallback in
views.py, since that fallback only looks for a not_available=False GW row
before falling back to product.msrp.

product.gw_url is populated with the Steamforged Games store product URL (not
a real GW link) -- this enables the "View" button on the product detail page,
same pattern as Star Wars: Legion / Halo: Flashpoint.

Usage:
    python manage.py populate_warmachine_products
"""

import decimal

from django.core.management.base import BaseCommand

from prices.models import CurrentPrice
from products.models import Category, Product, Retailer

