class Command(BaseCommand):
    """Populate the Warmachine product line (idempotent)."""

    help = 'Populates Warmachine products (WMH-001 to WMH-348).'

    def handle(self, *args, **options):
        category, _ = Category.objects.get_or_create(
            slug='warmachine',
            defaults={'name': 'Warmachine'},
        )

        steamforged, _ = Retailer.objects.get_or_create(
            slug='steamforged-games',
            defaults={
                'name': 'Steamforged Games',
                'website': 'https://warmachine.gg',
                'country': 'US',
                'is_active': True,
                'is_uk': False,
            },
        )

        products_created = 0
        products_updated = 0
        steamforged_prices_created = 0
        steamforged_prices_updated = 0

        for slug, gw_sku, name, msrp, image_url, product_url, ebay_search_name in PRODUCTS:
            product, created = Product.objects.update_or_create(
                slug=slug,
                defaults={
                    'gw_sku': gw_sku,
                    'name': name,
                    'category': category,
                    'msrp': msrp,
                    'image_url': image_url,
                    'gw_url': product_url,
                    'ebay_search_name': ebay_search_name,
                    'batch_tag': 'warmachine',
                    'is_active': True,
                },
            )
            if created:
                products_created += 1
            else:
                products_updated += 1

            _, steamforged_price_created = CurrentPrice.objects.update_or_create(
                product=product,
                retailer=steamforged,
                defaults={
                    'price': msrp,
                    'url': product_url,
                    'in_stock': True,
                    'not_available': False,
                },
            )
            if steamforged_price_created:
                steamforged_prices_created += 1
            else:
                steamforged_prices_updated += 1

        self.stdout.write(self.style.SUCCESS(
            f'Products: {products_created} created, {products_updated} updated.'
        ))
        self.stdout.write(self.style.SUCCESS(
            f'Steamforged Games prices: {steamforged_prices_created} created, {steamforged_prices_updated} updated.'
        ))
